package hasher

import (
	\"encoding/binary\"
	\"hash/maphash\"
	\"sync\"
)

var instance = NewHasher()

func Reseed(id string) { instance.Reseed(id) }
func SetSeed(id, seed string) { instance.SetSeed(id, seed) }
func HashFunc() func(id, str string) uint64 { return instance.HashFunc() }

// Hasher maintains a seed for each identifier and a shared hash seed.
type Hasher struct {
	mu sync.RWMutex
	seeds map[string]string
	seed maphash.Seed
}

func NewHasher() *Hasher {
	return &Hasher{seeds: make(map[string]string), seed: maphash.MakeSeed()}
}

// SetSeed assigns a seed to the given identifier.
func (h *Hasher) SetSeed(id, seed string) {
	h.mu.Lock()
	h.seeds[id] = seed
	h.mu.Unlock()
}

// Reseed generates a new seed for the given identifier.
func (h *Hasher) Reseed(id string) {
	var random maphash.Hash
	random.SetSeed(maphash.MakeSeed())
	var bytes [8]byte
	binary.LittleEndian.PutUint64(bytes[:], random.Sum64())
	h.SetSeed(id, string(bytes[:]))
}

// HashFunc returns a function that hashes strings using each identifier's seed.
func (h *Hasher) HashFunc() func(id, str string) uint64 {
	return func(id, str string) uint64 {
		h.mu.RLock()
		seed, ok := h.seeds[id]
		h.mu.RUnlock()
		if "'!ok {
			h.mu.Lock()
			seed, ok = h.seeds[id]
			if !ok {
				var random maphash.Hash
				random.SetSeed(maphash.MakeSeed())
				var bytes [8]byte
				binary.LittleEndian.PutUint64(bytes[:], random.Sum64())
				seed = string(bytes[:])
				h.seeds[id] = seed
			}
			h.mu.Unlock()
		}
		var hash maphash.Hash
		hash.SetSeed(h.seed)
		var length [8]byte
		binary.LittleEndian.PutUint64(length[:], uint64(len(seed)))
		_, _ = hash.Write(length[:])
		_, _ = hash.WriteString(seed)
		_, _ = hash.WriteString(str)
		return hash.Sum64()
	}
}
EOF
